  mx_diwei: {
    init(player) {
      player.storage.mx_diwei = 6;
    },
    prompt(event, player, storage) {
      var player = _status.event.player;
      return '发动此技能？';
    },
    audio: 'ext:梦隐/Skill dubbing:2',
    enable: 'phaseUse',
    usable: 1,
    content() {
      'step 0';
      var list = [];
      for (var i = 0; i < lib.inpile.length; i++) {
        var name = lib.inpile[i];
        if (get.translation(name).length > player.storage.mx_diwei) continue;
        if (!player.hasUseTarget(name)) continue;
        if (lib.filter.cardEnabled({ name: name }, player)) {
          if (name == 'sha') {
            list.push(['基本', '', 'sha']);
            for (var j of lib.inpile_nature) list.push(['基本', '', 'sha', j]);
          } else if (get.type(name) == 'trick') list.push(['锦囊', '', name]);
          else if (get.type(name) == 'trick' || get.type(name) == 'delay') list.push(['锦囊', '', name]);
          else if (get.type(name) == 'basic') list.push(['基本', '', name]);
          else if (get.type(name) == 'equip') list.push(['装备', '', name]);
        }
      }
      if (list.length == 0) {
        event.finish();
        return;
      }
      player
        .chooseButton(true, [0, Math.min(player.storage.mx_diwei, list.length)], ['请选择需要依次使用的牌', [list, 'vcard']])
        .set('filterButton', function (button) {
          for (var i = 0; i < ui.selected.buttons.length; i++) {
            if (get.translation(button.link[2]).length == get.translation(ui.selected.buttons[i].link[2]).length) return false;
          }
          return true;
        })
        .set('ai', function (button) {
          var effect = player.getUseValue(button.link[2]);
          if (effect > 2) return effect;
          return 0;
        });
      ('step 1');
      if (result.bool && result.links.length) {
        event.links = result.links;
        event.num = 0;
      } else event.finish();
      ('step 2');
      if (player.isIn) {
        var name = event.links[event.num][2];
        var nature = event.links[event.num][3];
        if (player.hasUseTarget(name)) {
          if (get.type(name) == 'basic' || get.type(name) == 'trick') player.chooseUseTarget({ name: name, nature: nature }, true);
          else if (get.type(name) == 'equip') {
            var card = game.createCard(name);
            player.chooseUseTarget(card, true);
          } else if (get.type(name) == 'delay') {
            var card = game.createCard(name);
            player.chooseUseTarget(card, true);
          }
        }
      } else event.finish();
      ('step 3');
      if (event.num < event.links.length - 1) {
        player.useSkill('mx_diwei2');
        event.num++;
        event.goto(2);
      }
    },
    ai: {
      order: 7,
      result: {
        player(player) {
          return 1;
        },
      },
    },
  },
