  mx_hanzui2: {
    usable: 1,
    trigger: {
      player: '',
    },
    filter(event, player) {
      if (!player.countCards('h')) return false;
      return game.hasPlayer(function (current) {
        if (player == current) return false;
        return current.countCards('h');
      });
    },
    check(event, player) {
      if (
        !player.countCards('h', function (card) {
          return 6 - get.value(card);
        })
      )
        return false;
      return game.hasPlayer(function (current) {
        if (!current.countCards('h')) return false;
        return get.attitude(player, current) < 0;
      });
    },
    content() {
      'step 0';
      event.hc = player.getCards('h');
      event.ts = [];
      event.i = 0;
      ('step 1');
      var hc = event.hc;
      var ts = event.ts;
      var fc = event.i > 0 ? false : true;
      player.chooseCardTarget({
        prompt: '你可以与其他角色交换任意张未交换过的手牌',
        selectCard: [1, Infinity],
        filterCard(card, player) {
          return hc.includes(card);
        },
        forced: fc,
        complexCard: true,
        complexTarget: true,
        complexSelect: true,
        filterTarget(card, player, target) {
          if (player == target) return false;
          if (ts.includes(target)) return false;
          return target.countCards('h') > ui.selected.cards.length - 1;
        },
        ai1(card) {
          return 6 - get.value(card);
        },
        ai2(target) {
          var player = get.player();
          return -get.attitude(player, target);
        },
      });
      ('step 2');
      if (result.bool) {
        event.cs1 = result.cards;
        event.target = result.targets[0];
        player.line(event.target, 'green');
        player.randomDiscard('j');
        var att = get.attitude(player, event.target);
        event.target.chooseCard('请选择交换的手牌', 'h', true, event.cs1.length).set('ai', function (card) {
          if (att > 0) return get.value(card);
          return 6 - get.value(card);
        });
        event.i++;
        event.ts.push(event.target);
        for (var i = 0; i < event.cs1.length; i++) {
          event.hc.remove(event.cs1[i]);
        }
      } else event.finish();
      ('step 3');
      event.cs2 = result.cards;
      player.lose(event.cs1, ui.special);
      event.target.lose(event.cs2, ui.special);
      player.gain(event.cs2, event.target, 'giveAuto');
      event.target.gain(event.cs1, player, 'giveAuto');
      ('step 4');
      if (event.hc.length) {
        var ts = event.ts;
        if (
          game.hasPlayer(function (current) {
            if (player == current) return false;
            if (ts.includes(current)) return false;
            return current.countCards('h');
          })
        )
          event.goto(1);
      }
    },
  },
