  mx_shizhemanyan: {
    audio: 'ext:梦隐/Skill dubbing:2',
    trigger: {
      global: 'linkBegin',
    },
    filter(event, player) {
      return event.player.isEnemiesOf(player);
    },
    forced: true,
    content() {
      'step 0';
      if (!player.countCards('hej', { suit: 'heart' })) {
        var basiclist = [];
        basiclist.push(['基本', '', 'sha']);
        basiclist.push(['基本', '', 'sha', 'fire']);
        basiclist.push(['基本', '', 'sha', 'thunder']);
        basiclist.push(['基本', '', 'sha', 'ice']);
        basiclist.push(['基本', '', 'jiu']);
        basiclist.push(['基本', '', 'tao']);
        player.chooseButton(['视为使用其中的一张基本牌？', [basiclist, 'vcard']], false).set('ai', function (button) {
          if (player.isDamaged()) {
            if (button.link[2] == 'tao') return 9;
          } else if (button.link[2] == 'sha' && button.link[3] == 'ice') return 4;
          return 1;
        });
      } else event.goto(2);
      ('step 1');
      if (result && result.bool && result.links[0]) {
        player.addTempSkill('mx_shizhemanyan2', { player: 'mx_shizhemanyanAfter' });
        player.chooseUseTarget({ name: result.links[0][2], nature: result.links[0][3] }, false);
      }
      ('step 2');
      if (!player.countCards('hej', { suit: 'spade' })) {
        var tricklist = [];
        for (var i = 0; i < lib.inpile.length; i++) {
          if (get.type(lib.inpile[i]) == 'trick' && lib.filter.cardEnabled({ name: lib.inpile[i] }, player)) tricklist.push(['锦囊', '', lib.inpile[i]]);
        }
        player.chooseButton(['视为使用其中的一张普通锦囊牌？', [tricklist, 'vcard']], false).set('ai', function (button) {
          var recover = 0,
            lose = 1,
            players = game.filterPlayer();
          for (var i of players) {
            if (i.hp == 1 && get.damageEffect(i, player, player) > 0 && !i.hasSha()) {
              return button.link[2] == 'juedou' ? 2 : -1;
            }
            if (!i.isOut()) {
              if (i.hp < i.maxHp) {
                if (get.attitude(player, i) > 0) {
                  if (i.hp < 2) {
                    lose--;
                    recover += 0.5;
                  }
                  lose--;
                  recover++;
                } else if (get.attitude(player, i) < 0) {
                  if (i.hp < 2) {
                    lose++;
                    recover -= 0.5;
                  }
                  lose++;
                  recover--;
                }
              } else {
                if (get.attitude(player, i) > 0) {
                  lose--;
                } else if (get.attitude(player, i) < 0) {
                  lose++;
                }
              }
            }
          }
          if (lose > recover && lose > 0) return button.link[2] == 'nanman' ? 1 : -1;
          if (lose < recover && recover > 0) return button.link[2] == 'taoyuan' ? 1 : -1;
          return button.link[2] == 'wuzhong' ? 1 : -1;
        });
      } else event.finish();
      ('step 3');
      if (result && result.bool && result.links[0]) {
        player.addTempSkill('mx_shizhemanyan2', { player: 'mx_shizhemanyanAfter' });
        player.chooseUseTarget({ name: result.links[0][2], nature: result.links[0][3] }, false);
      }
    },
  },
