        var nh = 0,
          pn = 0;
        for (var i of game.players) {
          if (i.isOut() || i == player) continue;
          pn++;
          if (i.countCards('h') > nh) {
            nh = i.countCards('h');
          }
        }
        var num1 = Math.max(1, player.countCards('h') - nh + 1);
        var tp = Math.min(pn, num1);
