  mx_tiechunv: {
    audio: 'ext:梦隐/Skill dubbing:2',
    enable: ['chooseToUse', 'chooseToRespond'],
    filterCard(card, player) {
      return get.type(card) == 'basic';
    },
    usable: 1,
    viewAs: {
      name: 'sha',
      storage: {
        mx_tiechunv: true,
      },
    },
    viewAsFilter(player) {
      if (
        !player.countCards('hes', function (card) {
          return get.type(card) == 'basic';
        })
      )
        return false;
    },
    position: 'hes',
    selectCard() {
      return _status.event.skill == 'mx_tiechunv' ? 1 : Infinity;
    },
    precontent() {
      if (player != _status.currentPhase) player.draw();
      event.parent.addCount = false;
    },
    prompt: '将一张基本牌当无距离限制的【杀】使用或打出',
    check(card) {
      var val = get.value(card);
      if (_status.event.name == 'chooseToRespond') return 1 / Math.max(0.1, val);
      return 6 - val;
    },
    ai: {
      order(item, player) {
        var target = _status.currentPhase;
        if (!target || target != player) return 7;
        return 1;
      },
      respondSha: true,
      skillTagFilter(player) {
        if (
          !player.countCards('hes', function (card) {
            return get.type(card) == 'basic';
          })
        )
          return false;
      },
      yingbian(card, player, targets, viewer) {
        if (get.attitude(viewer, player) <= 0) return 0;
        var base = 0,
          hit = false;
        if (get.cardtag(card, 'yingbian_hit')) {
          hit = true;
          if (
            targets.some((target) => {
              return target.mayHaveShan(viewer) && get.attitude(viewer, target) < 0 && get.damageEffect(target, player, viewer, get.natureList(card)) > 0;
            })
          )
            base += 5;
        }
        if (get.cardtag(card, 'yingbian_add')) {
          if (
            game.hasPlayer(function (current) {
              return !targets.includes(current) && lib.filter.targetEnabled2(card, player, current) && get.effect(current, card, player, player) > 0;
            })
          )
            base += 5;
        }
        if (get.cardtag(card, 'yingbian_damage')) {
          if (
            targets.some((target) => {
              return (
                get.attitude(player, target) < 0 &&
                (hit ||
                  !target.mayHaveShan(viewer) ||
                  player.hasSkillTag(
                    'directHit_ai',
                    true,
                    {
                      target: target,
                      card: card,
                    },
                    true
                  )) &&
                !target.hasSkillTag('filterDamage', null, {
                  player: player,
                  card: card,
                  jiu: true,
                })
              );
            })
          )
            base += 5;
        }
        return base;
      },
      canLink(player, target, card) {
        if (!target.isLinked() && !player.hasSkill('wutiesuolian_skill')) return false;
        if (
          target.mayHaveShan() &&
          !player.hasSkillTag(
            'directHit_ai',
            true,
            {
              target: target,
              card: card,
            },
            true
          )
        )
          return false;
        if (player.hasSkill('jueqing') || player.hasSkill('gangzhi') || target.hasSkill('gangzhi')) return false;
        return true;
      },
      basic: {
        useful: [5, 3, 1],
        value: [5, 3, 1],
      },
      result: {
        target(player, target, card, isLink) {
          var eff = (function () {
            if (!isLink && player.hasSkill('jiu')) {
              if (
                !target.hasSkillTag('filterDamage', null, {
                  player: player,
                  card: card,
                  jiu: true,
                })
              ) {
                if (get.attitude(player, target) > 0) {
                  return -7;
                } else {
                  return -4;
                }
              }
              return -0.5;
            }
            return -1.5;
          })();
          if (
            !isLink &&
            target.mayHaveShan() &&
            !player.hasSkillTag(
              'directHit_ai',
              true,
              {
                target: target,
                card: card,
              },
              true
            )
          )
            return eff / 1.2;
          return eff;
        },
      },
      tag: {
        respond: 1,
        respondShan: 1,
        damage(card) {
          if (game.hasNature(card, 'poison')) return;
          return 1;
        },
        natureDamage(card) {
          if (game.hasNature(card, 'linked')) return 1;
        },
        fireDamage(card, nature) {
          if (game.hasNature(card, 'fire')) return 1;
        },
        thunderDamage(card, nature) {
          if (game.hasNature(card, 'thunder')) return 1;
        },
        poisonDamage(card, nature) {
          if (game.hasNature(card, 'poison')) return 1;
        },
        mx_duDamage(card, nature) {
          if (card.nature == 'mx_du') return 1;
        },
        mx_xieDamage(card, nature) {
          if (card.nature == 'mx_xie') return 1;
        },
      },
    },
    mod: {
      targetInRange(card) {
        if (card.storage && card.storage.mx_tiechunv) return true;
      },
      cardUsable(card, player, num) {
        if (card.storage && card.storage.mx_tiechunv) return Infinity;
      },
    },
  },
