  mx_chizhixingtong: {
    audio: 'ext:梦隐/Skill dubbing:2',
    enable: 'phaseUse',
    filterCard: true,
    selectCard() {
      var player = _status.event.player;
      var num = Math.max(1, player.countCards('h') - player.getHandcardLimit());
      return [1, num];
    },
    complexCard: true,
    discard: false,
    loseTo: 'cardPile',
    insert: true,
    visible: true,
    delay: false,
    position: 'he',
    usable: 1,
    check(card) {
      if (ui.selected.cards.length >= 3) return 0;
      var player = _status.event.player;
      var num = Math.max(1, player.countCards('h') - player.getHandcardLimit());
      if (num >= 3) return 5 - get.value(card);
      if (num >= 2 && player.isDamaged() && ui.selected.cards.length < 1) return 7 - get.value(card);
      if (num >= 1 && player.isDamaged() && !ui.selected.cards.length) return 6 - get.value(card);
      return 0;
    },
    //出牌阶段限一次,你可以将至多X张牌以任意顺序置于牌堆顶或牌堆底.若以此法失去的牌数:不小于4,你下次造成的伤害值翻倍;不小于3,你可以视为依次使用两张【决斗】;不小于2,你摸一张牌.此流程结算前,你获得一张【决斗】;你的手牌上限+M(X为你的手牌数与手牌上限之差;Y为你发动此技能的次数)
    content() {
      'step 0';
      player.addTempSkill('mx_chizhixingtong3', { player: 'phaseUseAfter' });
      player.$throw(cards.length);
      player
        .chooseToMove()
        .set('list', [['牌堆顶', cards], ['牌堆底']])
        .set('prompt', '赤之星曈')
        .set('processAI', function (list) {
          var cards = list[0][1];
          const target = player.next;
          const att = get.attitude(player, target);
          const top = [],
            bottom = cards;
          for (const i of target.getCards('j')) {
            const judge = get.judge(i);
            bottom.sort((a, b) => (judge(b) - judge(a)) * att); //态度大于0价值高的牌放前面
            if (bottom.length) {
              top.push(bottom.shift());
            }
          }
          bottom.sort((a, b) => (get.value(b) - get.value(a)) * att); //态度大于0价值高的牌放前面
          while (bottom.length) {
            top.push(bottom.shift());
          }
          return [top, bottom];
        }); //给别人观星
      ('step 1');
      var top = result.moved[0];
      var bottom = result.moved[1];
      top.reverse();
      for (var i = 0; i < top.length; i++) {
        top[i].fix();
        ui.cardPile.insertBefore(top[i], ui.cardPile.firstChild);
      }
      for (var i = 0; i < bottom.length; i++) {
        bottom[i].fix();
        ui.cardPile.appendChild(bottom[i]);
      }
      player.gain(game.createCard('juedou'), 'gain');
      player.popup(get.cnNumber(top.length) + '顶' + get.cnNumber(bottom.length) + '底');
      game.log(player, '将' + get.cnNumber(top.length) + '张牌置于牌堆顶');
      game.updateRoundNumber();
      ('step 2');
      if (cards.length >= 4) player.addTempSkill('mx_chizhixingtong2', { player: 'mx_chizhixingtong2After' });
      ('step 3');
      if (cards.length >= 3) {
        player.chooseUseTarget(false, { name: 'juedou' });
        player.chooseUseTarget(false, { name: 'juedou' });
      }
      ('step 4');
      if (cards.length >= 2) {
        player.draw();
        player.addSkill('mx_chizhixingtong_effect');
        player.addMark('mx_chizhixingtong_effect', 1, false);
      }
    },
    ai: {
      order: 5,
      result: {
        player: 1,
      },
    },
    subSkill: {
      effect: {
        charlotte: true,
        marktext: '✡︎',
        intro: {
          content: '你的手牌上限+#',
        },
        mod: {
          maxHandcard(player, num) {
            return num + player.countMark('mx_chizhixingtong_effect');
          },
        },
      },
    },
  },
