  mx_cuoqie: {
    audio: 'ext:梦隐/Skill dubbing:2',
    group: ['mx_cuoqie2', 'mx_cuoqie3'],
    usable: 1,
    enable: ['chooseToUse'],
    filterCard: true,
    selectCard() {
      return -1;
    },
    position: 'h',
    viewAs: {
      name: 'sha',
    },
    filter(event, player) {
      return player.countCards('h') > 0;
    },
    check(card) {
      if (card.name == 'sha') return -1;
      return 6 - get.useful(card);
    },
    ai: {
      order() {
        return (
          get.order({
            name: 'sha',
          }) + 0.1
        );
      },
      respondSha: true,
      skillTagFilter(player) {
        return player.countCards('h') > 0;
      },
      canLink(player, target, card) {
        if (!target.isLinked() && !player.hasSkill('wutiesuolian_skill')) return false;
        if (
          target.mayHaveShan() &&
          !player.hasSkillTag(
            'directHit_ai',
            true,
            {
              target: target,
              card: card,
            },
            true
          )
        )
          return false;
        if (player.hasSkill('jueqing') || player.hasSkill('gangzhi') || target.hasSkill('gangzhi')) return false;
        return true;
      },
      basic: {
        useful: [5, 3, 1],
        value: [5, 3, 1],
      },
      result: {
        player(player) {
          var num = 0;
          var cards = player.getCards('h');
          if (cards.length >= 3 && player.hp >= 3) return -10;
          if (Array.isArray(cards))
            for (var i of cards) {
              if (i.name == 'sha') return -100;
              num += Math.max(0, get.value(i, player, 'raw'));
            }
          num /= cards.length;
          num *= Math.min(cards.length, player.hp);
          if (12 - num < 0) return -100;
          return 0;
        },
        target(player, target, card, isLink) {
          var eff = (function () {
            if (!isLink && player.hasSkill('jiu')) {
              if (
                !target.hasSkillTag('filterDamage', null, {
                  player: player,
                  card: card,
                  jiu: true,
                })
              ) {
                if (get.attitude(player, target) > 0) {
                  return -7;
                } else {
                  return -4;
                }
              }
              return -0.5;
            }
            return -1.5;
          })();
          if (
            !isLink &&
            target.mayHaveShan() &&
            !player.hasSkillTag(
              'directHit_ai',
              true,
              {
                target: target,
                card: card,
              },
              true
            )
          )
            return eff / 1.2;
          return eff;
        },
      },
      tag: {
        respond: 1,
        respondShan: 1,
        damage(card) {
          if (card.nature == 'poison') return;
          return 1;
        },
        natureDamage(card) {
          if (card.nature) return 1;
        },
        fireDamage(card, nature) {
          if (card.nature == 'fire') return 1;
        },
        thunderDamage(card, nature) {
          if (card.nature == 'thunder') return 1;
        },
        poisonDamage(card, nature) {
          if (card.nature == 'poison') return 1;
        },
        mx_duDamage(card, nature) {
          if (card.nature == 'mx_du') return 1;
        },
        mx_xieDamage(card, nature) {
          if (card.nature == 'mx_xie') return 1;
        },
      },
      yingbian(card, player, targets, viewer) {
        if (get.attitude(viewer, player) <= 0) return 0;
        var base = 0,
          hit = false;
        if (get.cardtag(card, 'yingbian_hit')) {
          hit = true;
          if (
            targets.some((target) => {
              return target.mayHaveShan(viewer) && get.attitude(viewer, target) < 0 && get.damageEffect(target, player, viewer, get.natureList(card)) > 0;
            })
          )
            base += 5;
        }
        if (get.cardtag(card, 'yingbian_add')) {
          if (
            game.hasPlayer(function (current) {
              return !targets.includes(current) && lib.filter.targetEnabled2(card, player, current) && get.effect(current, card, player, player) > 0;
            })
          )
            base += 5;
        }
        if (get.cardtag(card, 'yingbian_damage')) {
          if (
            targets.some((target) => {
              return (
                get.attitude(player, target) < 0 &&
                (hit ||
                  !target.mayHaveShan(viewer) ||
                  player.hasSkillTag(
                    'directHit_ai',
                    true,
                    {
                      target: target,
                      card: card,
                    },
                    true
                  )) &&
                !target.hasSkillTag('filterDamage', null, {
                  player: player,
                  card: card,
                  jiu: true,
                })
              );
            })
          )
            base += 5;
        }
        return base;
      },
    },
  },
