    check(card) {
      if (_status.event.name == 'chooseToRespond') {
        if (card.name == 'sha') return 0;
        return 6 - get.useful(card);
      }
      if (_status.event.player.countCards('hs') < 4) return 6 - get.useful(card);
      return 7 - get.useful(card);
    },
    group: 'mx_xuemonv_damage',
