  mx_dongganxuanku: {
    audio: 'ext:梦隐/Skill dubbing:2',
    enable: ['chooseToUse', 'chooseToRespond'],
    filter(event, player) {
      return player.isHealthy();
    },
    chooseButton: {
      dialog(event, player) {
        var list = [];
        for (var i = 0; i < lib.inpile.length; i++) {
          var name = lib.inpile[i];
          if (name == 'sha') {
            list.push(['基本', '', 'sha']);
            list.push(['基本', '', 'sha', 'fire']);
            list.push(['基本', '', 'sha', 'thunder']);
            list.push(['基本', '', 'sha', 'ice']);
          } else if (get.type(name) == 'trick') list.push(['锦囊', '', name]);
          else if (get.type(name) == 'basic') list.push(['基本', '', name]);
        }
        if (list.length == 0) {
          return ui.create.dialog('无');
        }
        return ui.create.dialog('动感与炫酷', [list, 'vcard']);
      },
      filter(button, player) {
        var evt = _status.event.parent;
        if (player.storage.mx_dongganxuanku && player.storage.mx_dongganxuanku.includes(button.link[2])) return false;
        return evt.filterCard(
          {
            name: button.link[2],
          },
          player,
          evt
        );
      },
      check(button) {
        var player = _status.event.player;
        var name = button.link[2];
        if (player.countCards('h', name) > 0) return 0;
        var evt = _status.event.getParent('chooseToUse');
        if (evt && evt.type == 'dying') {
          if (
            evt.dying != player &&
            get.effect(
              evt.dying,
              {
                name: name,
              },
              player,
              player
            ) <= 0
          )
            return 0;
          if (evt.dying == player && name == 'jiu') return 2.1;
          return 2;
        }
        var effect = player.getUseValue(name);
        if (effect > 0) return effect;
        return 0;
      },
      backup(links, player) {
        return {
          filterCard(card, player) {
            return get.color(card) == 'black';
          },
          selectCard: 2,
          popname: true,
          check(card) {
            return 7.1 - get.value(card);
          },
          position: 'hes',
          viewAs: {
            name: links[0][2],
            nature: links[0][3],
          },
          onuse(result, player) {
            if (!player.storage.mx_dongganxuanku) player.storage.mx_dongganxuanku = [];
            player.storage.mx_dongganxuanku.add(result.card.name);
            var next = game.createEvent('mx_dongganxuanku_clear');
            next.player = player;
            _status.event.next.remove(next);
            var phase = _status.event.getParent('phase', true);
            if (phase) phase.after.push(next);
            next.setContent(function () {
              delete player.storage.mx_dongganxuanku;
            });
          },
          onrespond(result, player) {
            if (!player.storage.mx_dongganxuanku) player.storage.mx_dongganxuanku = [];
            player.storage.mx_dongganxuanku.add(result.card.name);
            var next = game.createEvent('mx_dongganxuanku_clear');
            next.player = player;
            _status.event.next.remove(next);
            var phase = _status.event.getParent('phase', true);
            if (phase) phase.after.push(next);
            next.setContent(function () {
              delete player.storage.mx_dongganxuanku;
            });
          },
        };
      },
      prompt(links, player) {
        return '将两张黑色牌当' + (get.translation(links[0][3]) || '') + get.translation(links[0][2]) + '使用或打出';
      },
    },
    hiddenCard(player, name) {
      if (
        player.countCards('he', {
          type: 'equip',
        }) *
        2 <
        Math.max(player.countCards('he'), 1)
      )
        return false;
      return name == 'wuxie';
    },
    ai: {
      save: true,
      respondSha: true,
      respondShan: true,
      skillTagFilter(player, tag, arg) {
        if (player.storage.mx_dongganxuanku && !player.hasSkill('radiance_douyan_3')) {
          if (tag == 'respondSha' && player.storage.mx_dongganxuanku.includes('sha')) return false;
          if (tag == 'respondShan' && player.storage.mx_dongganxuanku.includes('shan')) return false;
          if (tag == 'save') {
            if (player.storage.mx_dongganxuanku.includes('tao') && (arg != player || player.storage.mx_dongganxuanku.includes('jiu'))) return false;
          }
        }
        if (
          player.countCards('he', {
            type: 'equip',
          }) *
          2 <
          Math.max(player.countCards('he'), 1)
        )
          return false;
      },
      order: 10,
      result: {
        player: 1,
      },
    },
  },
