  mx_hunanguang: {
    audio: 'ext:梦隐/Skill dubbing:2',
    trigger: {
      global: 'useCardToPlayer',
    },
    filter(event, player) {
      if (player.countCards('e') <= 1) return false;
      if ('club' != event.card.suit) return false;
      return event.player != player && !event.targets.includes(player);
    },
    check(event, player) {
      var effect = 0;
      for (var i = 0; i < event.targets.length; i++) {
        effect -= get.effect(event.targets[i], event.card, event.player, player);
      }
      if (effect > 0) {
        if (player.hp == 1) {
          if (player.countCards('h', 'tao')) {
            effect = -10;
          } else effect = -20;
        }
        if (player.hp == 2) {
          effect = -6;
        }
        if (player.hp > 2) {
          effect = 0;
        }
        if (event.targets.length == 1) {
          if (event.targets[0].hp == 1) {
            effect += get.attitude(player, event.targets[0]);
          }
          if (event.targets[0].hp < player.hp) {
            effect++;
          }
        }
        if (event.card.name == 'tao') {
          effect += 14;
        }
        if (event.card.name == 'wuzhong') {
          effect += 7;
        }
        if (event.card.name == 'shunshou') {
          effect -= 14;
        }
        if (event.card.name == 'jiedao') {
          effect -= 7;
        }
      }
      return get.attitude(player, event.player) < 0 && effect >= 0;
    },
    logTarget: 'player',
    content() {
      'step 0';
      player.chooseToDiscard(2, '请弃置装备区内的两张牌', true, 'e');
      ('step 1');
      var num = trigger.player.hp;
      player.gainPlayerCard('hej', trigger.player, num, true);
      player.chooseToUse(true, (card, player, event) => lib.filter.cardEnabled(card, player, event));
      player.chooseToUse(true, (card, player, event) => lib.filter.cardEnabled(card, player, event));
    },
  },
