  mx_banyuyou: {
    audio: 'ext:梦隐/Skill dubbing:2',
    enable: ['chooseToRespond', 'chooseToUse'],
    filterCard(card, player) {
      var e = player.getEquip(5);
      if (!e) return false;
      return card.suit == e.suit;
    },
    position: 'hes',
    viewAs: {
      name: 'sha',
    },
    viewAsFilter(player) {
      var e = player.getEquip(5);
      if (!e) return false;
      var suit = e.suit;
      if (!player.countCards('hes', { suit: suit })) return false;
      return true;
    },
    prompt: '发动此技能？',
    check(card) {
      var value = get.value(card);
      if (get.subtype(card) == 'equip5') value += 7;
      if (get.position(card) == 'e' && get.subtype(card) == 'equip1') value += 2;
      if (get.position(card) == 'e' && card.name == 'zhuge') value += 1;
      if (card.name == 'zhuge') value += 1;
      return 20 - value;
    },
    ai: {
      skillTagFilter(player) {
        var e = player.getEquip(5);
        if (!e) return false;
        var suit = e.suit;
        if (!player.countCards('hes', { suit: suit })) return false;
      },
      respondSha: true,
      yingbian(card, player, targets, viewer) {
        if (get.attitude(viewer, player) <= 0) return 0;
        var base = 0,
          hit = false;
        if (get.cardtag(card, 'yingbian_hit')) {
          hit = true;
          if (
            targets.some((target) => {
              return target.mayHaveShan(viewer) && get.attitude(viewer, target) < 0 && get.damageEffect(target, player, viewer, get.natureList(card)) > 0;
            })
          )
            base += 5;
        }
        if (get.cardtag(card, 'yingbian_add')) {
          if (
            game.hasPlayer(function (current) {
              return !targets.includes(current) && lib.filter.targetEnabled2(card, player, current) && get.effect(current, card, player, player) > 0;
            })
          )
            base += 5;
        }
        if (get.cardtag(card, 'yingbian_damage')) {
          if (
            targets.some((target) => {
              return (
                get.attitude(player, target) < 0 &&
                (hit ||
                  !target.mayHaveShan(viewer) ||
                  player.hasSkillTag(
                    'directHit_ai',
                    true,
                    {
                      target: target,
                      card: card,
                    },
                    true
                  )) &&
                !target.hasSkillTag('filterDamage', null, {
                  player: player,
                  card: card,
                  jiu: true,
                })
              );
            })
          )
            base += 5;
        }
        return base;
      },
      canLink(player, target, card) {
        if (!target.isLinked() && !player.hasSkill('wutiesuolian_skill')) return false;
        if (
          target.mayHaveShan() &&
          !player.hasSkillTag(
            'directHit_ai',
            true,
            {
              target: target,
              card: card,
            },
            true
          )
        )
          return false;
        if (player.hasSkill('jueqing') || player.hasSkill('gangzhi') || target.hasSkill('gangzhi')) return false;
        return true;
      },
      basic: {
        useful: [5, 3, 1],
        value: [5, 3, 1],
      },
      order(item, player) {
        if (player.hasSkillTag('presha', true, null, true)) return 10;
        if (game.hasNature(item, 'linked')) {
          if (
            game.hasPlayer(function (current) {
              return current != player && current.isLinked() && player.canUse(item, current, null, true) && get.effect(current, item, player, player) > 0 && lib.card.sha.ai.canLink(player, current, item);
            }) &&
            game.countPlayer(function (current) {
              return current.isLinked() && get.damageEffect(current, player, player, get.nature(item)) > 0;
            }) > 1
          )
            return 3.1;
          return 3;
        }
        return 3.05;
      },
      result: {
        target(player, target, card, isLink) {
          var eff = (function () {
            if (!isLink && player.hasSkill('jiu')) {
              if (
                !target.hasSkillTag('filterDamage', null, {
                  player: player,
                  card: card,
                  jiu: true,
                })
              ) {
                if (get.attitude(player, target) > 0) {
                  return -7;
                } else {
                  return -4;
                }
              }
              return -0.5;
            }
            return -1.5;
          })();
          if (
            !isLink &&
            target.mayHaveShan() &&
            !player.hasSkillTag(
              'directHit_ai',
              true,
              {
                target: target,
                card: card,
              },
              true
            )
          )
            return eff / 1.2;
          return eff;
        },
      },
      tag: {
        respond: 1,
        respondShan: 1,
        damage(card) {
          if (game.hasNature(card, 'poison')) return;
          return 1;
        },
        natureDamage(card) {
          if (game.hasNature(card, 'linked')) return 1;
        },
        fireDamage(card, nature) {
          if (game.hasNature(card, 'fire')) return 1;
        },
        thunderDamage(card, nature) {
          if (game.hasNature(card, 'thunder')) return 1;
        },
        poisonDamage(card, nature) {
          if (game.hasNature(card, 'poison')) return 1;
        },
      },
    },
  },
