  mx_huangrumeng: {
    audio: 'ext:梦隐/Skill dubbing:4',
    enable: 'phaseUse',
    filter(event, player) {
      if (!player.next.isHealthy()) return false;
      return (
        player.countCards('h') > 0 &&
        !player.hasSkillTag('noCompareSource') &&
        game.hasPlayer(function (current) {
          return current != player && current.countCards('h') > 0 && !current.hasSkillTag('noCompareTarget');
        })
      );
    },
    filterTarget(card, player, target) {
      return target != player && target.countCards('h') > 0 && !target.hasSkillTag('noCompareTarget');
    },
    content() {
      'step 0';
      player.chooseToCompare(target);
      ('step 1');
      if (result.bool) {
        if (!target.countCards('hej')) event.finish();
        else {
          var num = target.getAttackRange() * 2;
          event.giver = target;
          event.gainner = player;
          player.randomDiscard(2, 'h');
          target.choosePlayerCard(target, true, 'hej', num, '交给' + get.translation(player) + '区域内的X张牌(X为你攻击范围的两倍)');
        }
      } else if (result.tie) {
        delete player.getStat('skill').refenglve;
        event.finish();
      } else {
        if (get.position(result.player, true) == 'd') player.addTempSkill('mx_huangrumeng2', { player: 'mx_huangrumeng2After' });
        event.finish();
      }
      ('step 2');
      if (result.bool) event.giver.give(result.cards, event.gainner);
    },
    ai: {
      order: 8,
      result: {
        target(player, target) {
          if (
            !player.hasCard(function (card) {
              if (get.position(card) != 'h') return false;
              var val = get.value(card);
              if (val < 0) return true;
              if (val <= 5) {
                return card.number >= 11;
              }
              if (val <= 6) {
                return card.number >= 13;
              }
              return false;
            })
          )
            return 0;
          return -Math.sqrt(1 + target.countCards('he')) / (1 + target.countCards('j'));
        },
      },
    },
  },
